<?php declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN']);?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Estado del sistema — Franky</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:#172033;font-family:Manrope,Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:82px 14px 32px}h1{margin:0}.sub{color:#64748b;margin:6px 0 18px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card{background:#fff;border:1px solid #e5eaf0;border-radius:16px;padding:14px}.k{font-size:10px;text-transform:uppercase;color:#64748b;font-weight:900}.v{font-size:20px;font-weight:900;margin-top:4px;word-break:break-word}.counts{margin-top:12px}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eef2f7}.row:last-child{border:0}@media(max-width:700px){.grid{grid-template-columns:1fr 1fr}.wrap{padding-left:12px;padding-right:12px}}</style></head><body><main class="wrap"><h1>Estado del sistema</h1><div class="sub">Salud técnica y volumen de Franky.</div><div id="c">Cargando…</div></main><script>const c=document.getElementById('c'),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));fetch('/api/estado-sistema.php').then(r=>r.json()).then(d=>{if(!d.ok)throw Error(d.error);c.innerHTML=`<div class="grid"><div class="card"><div class="k">Franky</div><div class="v">v${esc(d.version_app)}</div></div><div class="card"><div class="k">Commit</div><div class="v">${esc(d.commit)}</div></div><div class="card"><div class="k">PHP</div><div class="v">${esc(d.php)}</div></div><div class="card"><div class="k">MariaDB</div><div class="v">${esc(d.mariadb)}</div></div><div class="card"><div class="k">Hora servidor</div><div class="v" style="font-size:14px">${esc(d.server_time)}</div></div></div><div class="card counts">${Object.entries(d.counts).map(([k,v])=>`<div class="row"><strong>${esc(k)}</strong><span>${v??'—'}</span></div>`).join('')}</div>`}).catch(e=>c.textContent=e.message)</script></body></html>